const body=$json.body||{};
const workspace=body.workspace;
const approvedBy=String(body.approvedBy||'').trim();
if(body.mode!=='skill.publish'||!workspace||workspace.schemaVersion!==3||!approvedBy)return[{json:{ok:false,statusCode:400,error:'Schema v3 workspace and accountable approver are required.'}}];
const findings=[];
const pending=(workspace.reviewQueue||[]).filter(item=>item.status==='pending');
if(pending.length)findings.push(`${pending.length} human review decision(s) remain pending.`);
const names=new Set();
for(const skill of (workspace.skills||[]).filter(item=>item.status!=='retired')){const key=String(skill.name||'').trim().toLowerCase();if(names.has(key))findings.push(`${skill.name}: duplicate canonical name`);names.add(key);if(skill.status==='approved'){if(!String(skill.syntax?.action||'').trim()||!String(skill.syntax?.object||'').trim())findings.push(`${skill.name}: Action + Object syntax incomplete`);if(String(skill.description||'').trim().length<25)findings.push(`${skill.name}: definition too short`);if(String(skill.observability||'').trim().length<20)findings.push(`${skill.name}: observable evidence missing`);if(!Array.isArray(skill.evidence)||!skill.evidence.length)findings.push(`${skill.name}: source evidence missing`);}}
const approvedSkills=new Set((workspace.skills||[]).filter(item=>item.status==='approved').map(item=>item.id));
for(const mapping of (workspace.mappings||[]).filter(item=>item.status!=='rejected')){if(!approvedSkills.has(mapping.skillId))findings.push(`${mapping.id}: not grounded in an approved skill`);if(!String(mapping.rationale||'').trim()||!Array.isArray(mapping.evidence)||!mapping.evidence.length)findings.push(`${mapping.id}: evidence or rationale missing`);}
if(findings.length)return[{json:{ok:false,statusCode:409,error:'Release validation failed.',findings}}];
const now=new Date().toISOString();
const revision=Math.max(Number(workspace.revision||0),Number(workspace.publication?.revision||0))+1;
const released={...workspace,schemaVersion:3,revision,updatedAt:now,publication:{revision,state:'approved_release',approvedAt:now,approvedBy,githubPath:'data/skill-workspace.approved.json'},auditLog:[{id:`AUD-REL-${Date.now()}`,at:now,actor:'human',action:'workspace.released',entityType:'skill_workspace',entityId:`revision-${revision}`,summary:`Approved by ${approvedBy} and released to GitHub main.`},...(workspace.auditLog||[])].slice(0,250)};
return[{json:{ok:true,workspace:released,fileContent:JSON.stringify(released,null,2),commitMessage:`skill-taxonomy: release approved revision ${revision} [skip ci]`}}];
